/** @type {GameState} */
let S=load();
function load(){try{const s={...fresh(),...JSON.parse(localStorage.getItem('monsterBattleV5')||'{}')};if(s.battle){const q=QUESTS.find(x=>x.id===s.battle.quest);if(q)s.stamina=Math.min(s.maxStamina,s.stamina+q.cost);s.battle=null;s.page='home'}return s}catch{return fresh()}}
function save(){localStorage.setItem('monsterBattleV5',JSON.stringify(S))}
function toast(t){const d=document.createElement('div');d.className='toast';d.textContent=t;document.body.appendChild(d);setTimeout(()=>d.remove(),2200)}
function modal(h){const d=document.createElement('div');d.className='modal';d.id='modal';d.innerHTML=`<div class="sheet">${h}</div>`;document.body.appendChild(d)}
function closeModal(){document.getElementById('modal')?.remove();render()}
function stars(n){return '★'.repeat(n)}
function M(id){const b=MONSTERS[id],o=S.owned[id];if(!o?.evolved||!b.evolve)return b;return{...b,name:b.evolve,rarity:b.rarity+1,hp:Math.floor(b.hp*1.2),atk:Math.floor(b.atk*1.22)}}
function chooseStarter(id){S.starter=id;for(const x of [id,'ember','slime','rabit'])S.owned[x]={level:1,luck:1,evolved:false};S.party=[id,'ember','slime','rabit'];save();render();modal(`<div class="reveal"><div class="avatar">${M(id).icon}</div><h2>${M(id).name} と契約！</h2><button class="bigbtn" onclick="closeModal();go('quests')">冒険を始める</button></div>`)}
function header(){return `<header><div class="topline"><div class="brand">ASTRA CROWN<small>TYPE SCRIPT v5</small></div><div class="resources"><span class="pill">RANK <b>${S.rank}</b></span><span class="pill">⚡ ${S.stamina}/${S.maxStamina}</span><span class="pill">💎 ${S.gems}</span><span class="pill">🔷 ${S.crystals}</span><span class="pill">🪙 ${S.gold}</span></div></div></header>`}
function nav(){return `<nav class="nav">${[['home','🏠','ホーム'],['quests','⚔️','クエスト'],['box','🐾','BOX'],['gacha','✨','ガチャ'],['other','☰','その他']].map(([p,i,l])=>`<button class="${S.page===p?'active':''}" onclick="go('${p}')"><b>${i}</b>${l}</button>`).join('')}</nav>`}
function go(p){S.page=p;save();render()}
function render(){const a=$('#app');if(!S.starter){a.innerHTML=`<main><div class="starter-screen"><div class="starter-wrap"><h1>最初の相棒を選べ。</h1><p>モンスターを集め、育て、降臨へ挑むコマンドRPG。</p><div class="starter-grid">${['garum','livan','sylphin'].map(id=>cardStarter(id)).join('')}</div></div></div></main>`;return}a.innerHTML=header()+`<main id="main"></main>`+(S.battle?'':nav());const m=$('#main');if(S.battle)battleView(m);else({home:homeView,quests:questView,box:boxView,gacha:gachaView,other:otherView}[S.page]||homeView)(m);save()}
function cardStarter(id){const u=M(id);return `<div class="starter" onclick="chooseStarter('${id}')"><div class="bigicon">${u.icon}</div><span class="rarity">${stars(u.rarity)}</span><h3>${u.name}</h3><div class="tags"><span class="tag">${u.element}</span><span class="tag">${u.tribe}</span><span class="tag role">${u.role}</span></div><div class="passive-box tiny"><b>◆ ${u.passiveName}</b><br>${u.passiveDesc}</div></div>`}
function homeView(m){const lead=M(S.party[0]),o=S.owned[S.party[0]],pct=S.exp/needExp(S.rank)*100;m.innerHTML=`<section class="hero"><div class="tiny muted">MONSTER COLLECTION × COMMAND RPG</div><h1>一体一体に、<br>使う理由を。</h1><p>種族・役割・固有パッシブで編成を変え、通常クエストと降臨を攻略しよう。</p><button class="bigbtn" onclick="go('quests')">クエストへ</button></section><div class="section-title"><h2>プレイヤー</h2><span class="tiny muted">${S.exp}/${needExp(S.rank)} EXP</span></div><div class="card"><b>RANK ${S.rank}</b><div class="progress"><i style="width:${pct}%"></i></div></div><div class="section-title"><h2>リーダー</h2></div><div class="card"><div class="unit-row"><div class="avatar">${lead.icon}</div><div><b>${lead.name}</b><div class="tiny muted">🍀 ${o.luck}/99 · ${lead.role}</div><div class="passive-box tiny">◆ ${lead.passiveName} — ${lead.passiveDesc}</div></div></div></div>`}
function questView(m){m.innerHTML=`<div class="section-title"><div><div class="tiny muted">QUEST</div><h2>クエスト</h2></div></div><div class="notice">敵の属性・種族・ギミックを見て編成を変えよう。</div><div class="grid three" style="margin-top:14px">${QUESTS.map(q=>`<div class="card quest ${q.advent?'advent':''} ${S.rank<q.rank?'locked':''}" onclick="${S.rank<q.rank?'':`startQuest('${q.id}')`}"><div class="qicon">${q.icon}</div><div class="tiny muted">${q.advent?'降臨':'NORMAL'} · RANK ${q.rank}</div><h3>${q.name}</h3><div class="tiny muted">${q.enemy}</div><div class="tags"><span class="tag">${q.element}</span><span class="tag">${q.tribe}</span><span class="tag">⚡${q.cost}</span></div>${q.gimmickText?`<div class="gimmick">⚙ ${q.gimmickText}</div>`:''}</div>`).join('')}</div>`}
function startQuest(id){const q=QUESTS.find(x=>x.id===id);if(!q||S.stamina<q.cost){toast('スタミナが足りません');return}S.stamina-=q.cost;const fighters=S.party.map(id=>{const u=M(id),o=S.owned[id],max=Math.floor(u.hp*(1+(o.level-1)*.06));return{id,hp:max,maxHp:max,ult:0,guard:false}});S.battle={quest:id,enemyHp:q.hp,enemyMax:q.hp,round:1,turn:0,fighters,shield:0,debuff:0,barrier:q.gimmick==='barrier'?500:0,heat:0,aura:q.gimmick==='aura'?3:0,stunned:false,log:[`${q.enemy}が現れた！`]};if(fighters.some(f=>M(f.id).passive==='tailwind'))fighters.forEach(f=>f.ult=10);if(fighters.some(f=>M(f.id).passive==='moon'))S.battle.shield=.15;save();render()}
function Q(){return QUESTS.find(x=>x.id===S.battle.quest)}
function active(){return S.battle.fighters[S.battle.turn]}
function atkVal(id){const u=M(id),o=S.owned[id];return Math.floor(u.atk*(1+(o.level-1)*.055))}
